"""Read-only review of completed P1/P2 results; no training or selection."""
import json,hashlib
from pathlib import Path
import numpy as np
from scripts.ai7.runtime import ROOT
from scripts.ai7.research import seed_statistics

def main():
 r=ROOT/'benchmark-results/ai7-selfplay/p1p2-comparison/20261114-v1';o=ROOT/'benchmark-results/ai7-selfplay/p1p2-analysis/20261114-v1';o.mkdir(parents=True,exist_ok=False)
 c=json.loads((r/'comparison.json').read_text());out=[]
 for row in c['rows']:
  rows=[json.loads(s) for s in (r/'runs'/row['run_id']/'metrics.jsonl').read_text().splitlines()];ds=[m for m in rows if 'diagnostics' in m];grad=[g for m in ds for g in m['diagnostics']['gradients']]
  p=json.loads((r/'probes'/f"{row['run_id']}.json").read_text());old=ds[-1]['diagnostics']['probes'];new=p['final']['positions']
  symmetry=[{'index':i,'original_id':x['id'],'original_win_mass':x['groups']['immediate_win']['after'],'mirrored_win_mass':new[i]['groups']['immediate_win']['mass']} for i,x in enumerate(old) if 'immediate_win' in x['groups']]
  cos=[g['shared_actor_critic_cosine'] for g in grad if g['shared_actor_critic_cosine'] is not None]
  # Uniform per-update summaries are descriptive, not independent statistical samples.
  enrich={'row':row,'diagnostic_updates':len(ds),'sampled_minibatches':len(grad),'gradient_conflict_fraction':float(np.mean(np.array(cos)<0)),
   'draw_decision_fraction_mean':float(np.mean([m['diagnostics']['advantages']['by_outcome']['0']['decision_fraction'] for m in ds])),
   'draw_raw_positive_fraction_mean':float(np.mean([m['diagnostics']['advantages']['by_outcome']['0']['raw']['positive_fraction'] for m in ds if m['diagnostics']['advantages']['by_outcome']['0']['decisions']])),
   'explained_variance_last100_mean':float(np.mean([m['explained_variance'] for m in rows[-100:] if m.get('explained_variance') is not None])),
   'probe_symmetry':symmetry}
  out.append(enrich)
 (o/'review-data.json').write_text(json.dumps({'runs':out,'contrasts':c['matched_training_seed_architecture_differences']},indent=2)+'\n')
 lines=['# P1/P2 completed experiment review','','This report reuses completed results only. No weights, rewards, Core rules or training settings were changed. Nine runs reached3.64M steps each; three training seeds per treatment. All Random tests use256 deck pairs per policy; the single historical opponent uses64 pairs. Reported seed-level t intervals are exploratory, n=3, conditional on this fixed deck set, with no multiple-comparison adjustment.','', '## Outcome decomposition','','|Treatment|Initial W/D/L totals|Final W/D/L totals|Win change|Loss change|Mean score improvement|','|---|---|---|---:|---:|---:|']
 for name in ['baseline','low_lr','random_rich']:
  rr=[x['row'] for x in out if x['row']['architecture']==name];a=[sum(x['initial_'+k] for x in rr) for k in ['wins','draws','losses']];b=[sum(x['final_'+k] for x in rr) for k in ['wins','draws','losses']]
  lines.append(f"|{name}|{'/'.join(map(str,a))}|{'/'.join(map(str,b))}|{b[0]-a[0]:+}|{b[2]-a[2]:+}|{100*np.mean([x['score_improvement'] for x in rr]):.2f} pp|")
 lines+=['','Baseline now gains140 wins and removes109 losses across1536 games: +4.56pp from wins, +3.55pp from fewer losses. This contradicts applying the previous campaign’s “only fewer losses” diagnosis universally. Different training and evaluation seeds mean cross-campaign improvement itself is not a controlled treatment effect.','', '## Process diagnostics','','|Run|Probe KL p95|Worst one-update winning-mass change|Original probe peak→final|EV last100-update mean|Gradient cosine<0 sampled fraction|','|---|---:|---:|---|---:|---:|']
 for x in out:
  z=x['row'];lines.append(f"|{z['run_id']}|{z['probe_kl_p95']:.4f}|{100*z['worst_update_win_mass_change']:.2f} pp|{z['probe_win_mass_peak']:.3f}→{z['probe_win_mass_final']:.3f}|{x['explained_variance_last100_mean']:.3f}|{x['gradient_conflict_fraction']:.1%}|")
 lines+=['','Lower LR mechanically reduces changes but does not preserve strong general tactical ability. Original-probe peak/final ratios are descriptive and peak depends on visited checkpoints; they are not checkpoint-selection criteria. Final single-update EV can look positive while the last100-update mean remains negative; do not infer Critic recovery from the last row alone. Negative cosine remains common in every arm and does not identify a causal culprit.','', '## Fixed historical opponent','','|Treatment|Mean final score|Mean improvement from initial|Seed-level exploratory t95 improvement|','|---|---:|---:|---|']
 for name in ['baseline','low_lr','random_rich']:
  rr=[x['row'] for x in out if x['row']['architecture']==name];scores=[m['paired_score']['score'] for z in rr for m in z['frozen_opponent_matchups'] if m['checkpoint']=='final'];d=[v['difference'] for z in rr for v in z['frozen_opponent_comparisons']];stats=seed_statistics(d)
  lines.append(f"|{name}|{np.mean(scores):.3%}|{100*np.mean(d):.2f} pp|{stats['t95']}|")
 lines+=['','All treatment point estimates improve over their untrained policies against the historical opponent, so “zero generalization” would be too strong. However, finals remain close to50% against this one learned opponent. Random-rich has no demonstrated advantage over baseline on this generalization test. One opponent and64 pairs limit conclusions.','', '## Symmetry warning','','|Run|Original winning-probe mass|180-degree counterpart mass|','|---|---:|---:|']
 for x in out:
  for v in x['probe_symmetry']:lines.append(f"|{x['row']['run_id']} / {v['index']}|{v['original_win_mass']:.3f}|{v['mirrored_win_mass']:.3f}|")
 lines+=['','These are genuinely different public input vectors, including transformed public reveal references/history/action IDs, but geometrically equivalent rule tasks. Large disparities support representation/position sensitivity as a hypothesis. They do not isolate whether board position, reference coding, history or fixed action-head biases cause the difference. Mirror probes are not independent tactical task samples.','', '## Hypothesis assessment','','- P1: supported in the narrow sense of reduced update/probe volatility. The desired equal-step strength improvement is not supported: low-LR is lower in all three matched seeds; mean difference−5.92pp, exploratory t95[−10.57,−1.28]pp. This is not proof that low LR can never work at larger budgets.','- P2: increased wins versus initial in aggregate, but not reliably more than baseline: final mean contrast−1.92pp, exploratory t95[−9.12,+5.28]pp. No demonstrated overall advantage. Mirror winning probes improve, while original winning probes often decay. General tactical learning is not established.','- Critic-gradient harm: unproven. Gradient conflicts are associations and detailed samples cover only predetermined minibatches.','- Draw-driven reinforcement: plausible mechanism, not established intent or causal proof. Roughly70–75% of decisions come from drawn games, but only a subset has positive advantage, and normalized/clipped gradients cannot be interpreted from counts alone.','', '## Next experiments, not executed','','1. Evaluation-only symmetry audit: compare every saved checkpoint on the same original/rotated public states, per action, stage and public reference/history transformation. Add a larger fresh set of genuinely different Core-validated endgames before concluding tactical capability.','2. Deterministic targeted replays around large winning-probability drops; record all minibatches, actual pre/post-Adam parameter changes, and local counterfactual one-update actor-only/value-only/entropy-only branches from identical boundary state. These branch tests diagnose local effects, not full-training causal strength.','3. Only after those diagnostics, consider a separate symmetry-augmentation or board/action representation treatment. Board, legal mask, action IDs, history and public identity references must transform consistently; no tactical labels or shaped rewards.','4. Retain baseline as the current reference. If testing lower LR longer, compare equal steps AND equal total update displacement/compute explicitly; do not silently grant only one treatment more budget. Random40% is not adopted as default based on present evidence.','', 'No new training or configuration promotion was performed.']
 (o/'research-review.md').write_text('\n'.join(lines)+'\n');(o/'analysis-source.py').write_bytes(Path(__file__).read_bytes())
 print(o)
if __name__=='__main__':main()
